from pathlib import Path
p=Path('/mnt/data/pay_update/app/src/main/assets/index.html')
s=p.read_text()
old='''            <button type="button" id="btnSubmitTransferRequest" class="w-full sm:flex-1 py-2.5 px-3 rounded-xl shimmer-btn text-slate-950 font-extrabold text-xs shadow">\n              <i class="fa-solid fa-circle-check mr-1"></i>Kiểm Tra Thanh Toán &amp; Mở Khóa\n            </button>'''
new='''            <button type="button" id="btnSubmitTransferRequest" class="w-full sm:flex-1 py-2.5 px-3 rounded-xl shimmer-btn text-slate-950 font-extrabold text-xs shadow">\n              <i class="fa-solid fa-comment-dollar mr-1"></i>Tôi đã chuyển khoản – nhận mã mở khóa\n            </button>'''
assert old in s
s=s.replace(old,new,1)
old='''          <div id="pendingStatusBox" class="hidden w-full p-2.5 rounded-xl bg-amber-950/75 border border-amber-300/50 text-left text-[11px] space-y-1">\n            <div class="font-extrabold text-amber-200">\n              <i class="fa-solid fa-spinner fa-spin mr-1 text-amber-300"></i>Đang kiểm tra giao dịch <span id="pendingOrderIdText">#TV-0000</span>...\n            </div>\n            <p id="pendingStatusDetail" class="text-amber-100/85">Vui lòng đảm bảo bạn đã chuyển đúng số tiền và nội dung chuyển khoản.</p>\n          </div>'''
new='''          <div id="activationRequestPanel" class="hidden w-full p-3 rounded-xl bg-amber-950/80 border border-amber-300/60 text-left text-[11px] space-y-2">\n            <div class="font-extrabold text-amber-200 text-sm">BÁO CHUYỂN KHOẢN &amp; NHẬN MÃ</div>\n            <p class="text-amber-100/90">Vui lòng liên hệ số <strong class="text-emerald-300 text-sm">089.666.4467</strong> để xác nhận chuyển khoản và nhận mã kích hoạt.</p>\n            <div class="rounded-lg bg-black/40 p-2">\n              <div class="text-amber-100/70">MÃ YÊU CẦU CỦA BẠN</div>\n              <div class="flex items-center justify-between gap-2">\n                <strong id="activationRequestCode" class="font-mono tracking-widest text-lg text-white">TV26-XXXXXXXX</strong>\n                <button type="button" id="btnCopyRequestCode" class="px-2 py-1 rounded bg-white/10 text-amber-200">Sao chép</button>\n              </div>\n              <div id="activationRequestPackage" class="text-amber-100/75 mt-1">Gói mở khóa</div>\n            </div>\n            <button type="button" id="btnSendActivationEmail" class="w-full py-2 rounded-lg bg-cyan-500/20 border border-cyan-300/50 text-cyan-100 font-bold">\n              <i class="fa-solid fa-envelope mr-1"></i>Gửi yêu cầu về mikuthanh2305@gmail.com\n            </button>\n            <p class="text-amber-100/70">Nút trên sẽ mở ứng dụng email với nội dung đã điền sẵn; bạn cần nhấn Gửi. Sau khi nhận mã từ quản trị viên, nhập mã bên dưới.</p>\n            <div class="border-t border-amber-300/20 pt-2 space-y-2">\n              <label for="activationCodeInput" class="block font-bold text-amber-200">MÃ KÍCH HOẠT</label>\n              <input id="activationCodeInput" type="text" autocomplete="off" autocapitalize="characters" placeholder="TV26-XXXX-XXXX-XXXX" class="w-full rounded-lg bg-black/50 border border-amber-300/40 px-3 py-2 text-white font-mono tracking-wider outline-none" />\n              <button type="button" id="btnActivateWithCode" class="w-full py-2.5 rounded-lg bg-gradient-to-r from-emerald-300 to-amber-300 text-slate-950 font-extrabold">\n                <i class="fa-solid fa-unlock-keyhole mr-1"></i>KÍCH HOẠT MỞ KHÓA\n              </button>\n              <p id="activationCodeFeedback" class="text-amber-100/80"></p>\n            </div>\n          </div>'''
assert old in s
s=s.replace(old,new,1)
# Add persistence restore after state object
needle='''      };\n\n      // ---------- 3. POPULATE SELECT DROPDOWNS ----------'''
insert='''      };\n\n      // Lưu quyền đã kích hoạt trên thiết bị để không mất khi đóng ứng dụng.\n      try {\n        const savedUnlocks = JSON.parse(localStorage.getItem('tuvi_lachong_unlocks_v1') || 'null');\n        if (savedUnlocks && typeof savedUnlocks === 'object') {\n          state.unlockedAll = savedUnlocks.unlockedAll === true;\n          state.unlockedPalaces = { ...state.unlockedPalaces, ...(savedUnlocks.unlockedPalaces || {}) };\n        }\n      } catch (e) {}\n\n      // Mã offline dùng cho quy trình cấp mã thủ công. Công cụ quản trị đi kèm ZIP dùng cùng thuật toán.\n      const ACTIVATION_KEY = 'LAC_HONG_THIEN_CUNG_OWNER_KEY_2026_TEMP';\n      function activationDigest(value) {\n        const input = ACTIVATION_KEY + '|' + value;\n        let a = 0x811c9dc5, b = 0x9e3779b9, c = 0x85ebca6b;\n        for (let i = 0; i < input.length; i++) {\n          const x = input.charCodeAt(i);\n          a = Math.imul(a ^ x, 0x01000193);\n          b = Math.imul(b ^ (x + i), 0x27d4eb2d);\n          c = Math.imul(c ^ (x + (i << 1)), 0x165667b1);\n        }\n        const hex = n => (n >>> 0).toString(16).toUpperCase().padStart(8, '0');\n        return 'TV26-' + (hex(a) + hex(b) + hex(c)).slice(0, 4) + '-' + (hex(a) + hex(b) + hex(c)).slice(4, 8) + '-' + (hex(a) + hex(b) + hex(c)).slice(8, 12);\n      }\n      function persistUnlocks() {\n        try { localStorage.setItem('tuvi_lachong_unlocks_v1', JSON.stringify({ unlockedAll: state.unlockedAll, unlockedPalaces: state.unlockedPalaces })); } catch (e) {}\n      }\n      function makeActivationRequestCode() {\n        const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';\n        let out = '';\n        try {\n          const bytes = new Uint8Array(10);\n          if (window.crypto && window.crypto.getRandomValues) { window.crypto.getRandomValues(bytes); for (const b of bytes) out += chars[b % chars.length]; }\n          else throw new Error('no crypto');\n        } catch (e) { for (let i = 0; i < 10; i++) out += chars[Math.floor(Math.random() * chars.length)]; }\n        return 'REQ-' + out;\n      }\n\n      // ---------- 3. POPULATE SELECT DROPDOWNS ----------'''
assert needle in s
s=s.replace(needle,insert,1)
# Replace unlock function to persist
s=s.replace('''        closePaymentModal();\n        updateHeaderAndWalletUI();''','''        persistUnlocks();\n        closePaymentModal();\n        updateHeaderAndWalletUI();''',1)
# Replace click handler area
start=s.index("        // Real Commercial Pay-to-Unlock Verification Handler")
end=s.index("\n        document.getElementById('btnSwitchQrMode')", start)
replacement='''        // Thanh toán tự động đang tạm hoãn: báo chuyển khoản, nhận mã thủ công rồi kích hoạt.\n        let currentActivationRequest = null;\n        document.getElementById('btnSubmitTransferRequest').addEventListener('click', () => {\n          const is5k = state.paymentSelectedPkg === '5k';\n          const branch = getBranchByPalaceId(state.paymentTargetPalaceId);\n          const targetId = is5k ? (state.paymentTargetPalaceId || 'menh') : 'FULL';\n          const targetName = is5k ? (branch ? branch.cungName : 'Cung đang chọn') : 'Toàn bộ 12 cung';\n          const amount = is5k ? '5.000đ' : '10.000đ';\n          currentActivationRequest = { requestCode: makeActivationRequestCode(), pkg: is5k ? '5k' : '10k', targetId, targetName, amount };\n          document.getElementById('activationRequestCode').textContent = currentActivationRequest.requestCode;\n          document.getElementById('activationRequestPackage').textContent = `Gói: ${targetName} • ${amount}`;\n          document.getElementById('activationCodeFeedback').textContent = '';\n          document.getElementById('activationCodeInput').value = '';\n          document.getElementById('activationRequestPanel').classList.remove('hidden');\n        });\n\n        document.getElementById('btnCopyRequestCode').addEventListener('click', () => {\n          const code = currentActivationRequest && currentActivationRequest.requestCode;\n          if (!code) return;\n          const ta = document.createElement('textarea'); ta.value = code; document.body.appendChild(ta); ta.select();\n          try { document.execCommand('copy'); showToast('Đã sao chép mã yêu cầu ' + code); } catch (e) { showToast(code); }\n          document.body.removeChild(ta);\n        });\n\n        document.getElementById('btnSendActivationEmail').addEventListener('click', () => {\n          if (!currentActivationRequest) return;\n          const r = currentActivationRequest;\n          const subject = encodeURIComponent('Yêu cầu cấp mã kích hoạt Tử Vi Lạc Hồng ' + r.requestCode);\n          const body = encodeURIComponent(`Xin cấp mã kích hoạt ứng dụng Tử Vi Lạc Hồng\\nMã yêu cầu: ${r.requestCode}\\nGói: ${r.pkg}\\nPhạm vi: ${r.targetName}\\nMã cung: ${r.targetId}\\nSố tiền: ${r.amount}\\nVui lòng kiểm tra chuyển khoản và gửi lại mã kích hoạt.`);\n          window.location.href = `mailto:mikuthanh2305@gmail.com?subject=${subject}&body=${body}`;\n        });\n\n        document.getElementById('btnActivateWithCode').addEventListener('click', () => {\n          const feedback = document.getElementById('activationCodeFeedback');\n          if (!currentActivationRequest) { feedback.textContent = 'Vui lòng tạo mã yêu cầu trước khi nhập mã kích hoạt.'; return; }\n          const entered = (document.getElementById('activationCodeInput').value || '').trim().toUpperCase();\n          const r = currentActivationRequest;\n          const expected = activationDigest(`${r.requestCode}|${r.pkg}|${r.targetId}`);\n          if (entered !== expected) { feedback.textContent = 'Mã kích hoạt không đúng với yêu cầu này. Vui lòng kiểm tra lại.'; return; }\n          if (r.pkg === '10k') {\n            state.unlockedAll = true;\n            CUNG_CHUC_NANG.forEach(c => { state.unlockedPalaces[c.id] = true; });\n          } else {\n            state.unlockedPalaces[r.targetId] = true;\n            state.selectedPalaceId = r.targetId;\n          }\n          persistUnlocks();\n          feedback.textContent = 'Kích hoạt thành công! Nội dung chuyên sâu đã được mở.';\n          showToast('Đã kích hoạt thành công gói ' + r.targetName);\n          setTimeout(() => {\n            closePaymentModal(); updateHeaderAndWalletUI(); renderLasoGrid(); renderSelectedPalaceQuickBar(); renderMinimalTab(); renderDeepTab(); switchTab('tab-deep');\n          }, 650);\n        });\n'''
s=s[:start]+replacement+s[end:]
p.write_text(s)
